$ProgressPreference='SilentlyContinue'
function S($q, $pages=1){
  for($p=1;$p -le $pages;$p++){
    $u = 'https://api.github.com/search/issues?per_page=100&page=' + $p + '&q=' + [uri]::EscapeDataString($q)
    try { $r = Invoke-RestMethod -Uri $u -Headers @{ 'User-Agent'='ps-research'; 'Accept'='application/vnd.github+json' } } catch { "ERR: $($_.Exception.Message)"; return }
    if($p -eq 1){ "TOTAL: $($r.total_count)" }
    foreach($i in $r.items){ $lab = ($i.labels | ForEach-Object { $_.name }) -join ','; $cl = if($i.closed_at){ $i.closed_at.Substring(0,10) } else { '-' }; "#{0} | {1} | c:{2} | x:{3} | {4} | {5} | {6}" -f $i.number, $i.state, $i.created_at.Substring(0,10), $cl, $i.state_reason, $lab, $i.title }
  }
}
