$ProgressPreference='SilentlyContinue'
function I($n, $bodyMax=2500, $cMax=700, $maxC=8){
  $h = @{ 'User-Agent'='ps-research'; 'Accept'='application/vnd.github+json' }
  try { $i = Invoke-RestMethod -Uri "https://api.github.com/repos/anthropics/claude-code/issues/$n" -Headers $h } catch { "ERR $n : $($_.Exception.Message)"; return }
  $lab = ($i.labels | ForEach-Object { $_.name }) -join ','
  "######## #$($i.number) [$($i.state)/$($i.state_reason)] created $($i.created_at) closed $($i.closed_at) assoc=$($i.author_association) labels=$lab comments=$($i.comments)"
  "TITLE: $($i.title)"
  $b = [string]$i.body; if($b.Length -gt $bodyMax){ $b = $b.Substring(0,$bodyMax) + ' ...[trunc]' }
  "BODY: $b"
  if($i.comments -gt 0){
    try { $cs = Invoke-RestMethod -Uri "https://api.github.com/repos/anthropics/claude-code/issues/$n/comments?per_page=30" -Headers $h } catch { "ERR comments: $($_.Exception.Message)"; return }
    $k=0
    foreach($c in $cs){ $k++; if($k -gt $maxC){ "... more comments omitted"; break }; $t=[string]$c.body; if($t.Length -gt $cMax){ $t=$t.Substring(0,$cMax)+' ...[trunc]' }; "--- COMMENT by $($c.user.login) [$($c.author_association)] $($c.created_at): $t" }
  }
}
